import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"快捷键设置","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 全局（Global）","slug":"_1-全局-global","link":"#_1-全局-global","children":[{"level":3,"title":"全局快捷键分组","slug":"全局快捷键分组","link":"#全局快捷键分组","children":[]},{"level":3,"title":"功能按键分组","slug":"功能按键分组","link":"#功能按键分组","children":[]},{"level":3,"title":"快速导航鼠标触发分组","slug":"快速导航鼠标触发分组","link":"#快速导航鼠标触发分组","children":[]},{"level":3,"title":"录制快捷键","slug":"录制快捷键","link":"#录制快捷键","children":[]},{"level":3,"title":"收藏项专属快捷键","slug":"收藏项专属快捷键","link":"#收藏项专属快捷键","children":[]}]},{"level":2,"title":"2. 插件动作（Plugin Actions）","slug":"_2-插件动作-plugin-actions","link":"#_2-插件动作-plugin-actions","children":[]},{"level":2,"title":"3. 进程黑名单（Process Blacklist）","slug":"_3-进程黑名单-process-blacklist","link":"#_3-进程黑名单-process-blacklist","children":[]}],"relativePath":"zh-CN/user-guide/settings/hotkeys-page.md","filePath":"zh-CN/user-guide/settings/hotkeys-page.md","lastUpdated":1791112464000}'),s={name:"zh-CN/user-guide/settings/hotkeys-page.md"};function i(n,o,a,c,d,g){return t(),l("div",null,[...o[0]||(o[0]=[r('<h1 id="快捷键设置" tabindex="-1">快捷键设置 <a class="header-anchor" href="#快捷键设置" aria-label="Permalink to &quot;快捷键设置&quot;">​</a></h1><p>快捷键设置页面集中管理 Lertaro 的所有全局唤起按键、应用内导航快捷键、插件动作快捷方式以及前台进程过滤规则。页面顶部包含三个标签页：<strong>全局</strong>、<strong>插件动作</strong>与<strong>进程黑名单</strong>。</p><h2 id="_1-全局-global" tabindex="-1">1. 全局（Global） <a class="header-anchor" href="#_1-全局-global" aria-label="Permalink to &quot;1. 全局（Global）&quot;">​</a></h2><h3 id="全局快捷键分组" tabindex="-1">全局快捷键分组 <a class="header-anchor" href="#全局快捷键分组" aria-label="Permalink to &quot;全局快捷键分组&quot;">​</a></h3><ul><li><strong>显示/隐藏快速搜索</strong>：专属按键录制框。支持录制为<strong>单键双击模式</strong>（默认双击 <code>Ctrl</code>，亦可设为双击 <code>Alt</code> 或 <code>Shift</code>），或录制为<strong>常规组合键</strong>（如 <code>Alt+Space</code> 等）。</li><li><strong>默认打开完整面板</strong>：复选框（默认关闭）。开启后，全局唤起快捷键会改为打开完整窗口，而不是快速窗口。首次唤起时只将窗口置于前台并聚焦一次；窗口已显示但未激活时再次按下会重新激活，窗口已经激活时再次按下则默认切回快速窗口，开启“再次按下快捷键时关闭完整窗口”后则直接关闭。窗口不会自动保持置顶。</li><li><strong>全屏应用聚焦时仍然响应</strong>：复选框（默认关闭）。开启后，即使前台有独占全屏程序（如全屏游戏或视频），Lertaro 依然会响应快捷键呼出搜索框；保持关闭则自动放行按键不抢占焦点。</li><li><strong>快速跳转（Quick Jump）</strong>：默认 <code>Ctrl+G</code>。在各类文件对话框中按下即可直接跳转到最近在文件管理器中浏览过的目录。</li><li><strong>快速导航菜单</strong>：默认不分配快捷键。可为它分配一个可选的全局快捷键来打开级联式菜单。在桌面或普通应用中呼出时使用桌面上下文；在文件资源管理器和原生文件对话框中呼出时使用当前窗口上下文。即使普通前台保护会抑制全局快捷键，文件管理器和文件对话框仍会放行。</li></ul><h3 id="功能按键分组" tabindex="-1">功能按键分组 <a class="header-anchor" href="#功能按键分组" aria-label="Permalink to &quot;功能按键分组&quot;">​</a></h3><p>页面提供了一系列独立的按键录制控件，支持任意单键或组合键录制：</p><ul><li><strong>选中下一项 / 上一项</strong>：默认 <code>Ctrl+N</code> / <code>Ctrl+P</code>（与方向键 <code>↓</code> / <code>↑</code> 等效）。</li><li><strong>跳转结果修饰键</strong>：默认 <code>Ctrl</code>，配合数字键 <code>1</code>–<code>9</code> 即可在快速窗口中直达前 9 项结果。</li><li><strong>打开动作菜单</strong>：默认 <code>Ctrl+O</code>（与方向键 <code>→</code> 等效）。两者都作用于快速窗口以及文件对话框之外的内嵌卡片；完整窗口改用鼠标右键或 <code>Apps</code> 键打开同一个菜单。</li><li><strong>从选中项补全搜索词</strong>：默认 <code>Ctrl+Tab</code>。</li><li><strong>QuickLook 即时预览</strong>：默认 <code>Alt+P</code>。</li><li><strong>上/下一条关键字历史</strong>：默认 <code>Alt+Up</code> / <code>Alt+Down</code>。</li><li><strong>删除当前关键字历史</strong>：默认 <code>Ctrl+Delete</code>。</li><li><strong>打开完整搜索主窗口</strong>：默认 <code>Ctrl+F</code>。</li><li><strong>打开发送窗口（LocalSend）</strong>：默认 <code>Ctrl+S</code>。</li><li><strong>保持窗口不消失（钉住）</strong>：默认 <code>Ctrl+T</code>。</li><li><strong>呼出/关闭快速面板</strong>：默认 <code>Ctrl+F2</code>。</li></ul><h3 id="快速导航鼠标触发分组" tabindex="-1">快速导航鼠标触发分组 <a class="header-anchor" href="#快速导航鼠标触发分组" aria-label="Permalink to &quot;快速导航鼠标触发分组&quot;">​</a></h3><ul><li><strong>在空白处双击左键</strong>：复选框（<strong>默认关闭</strong>）。在桌面或文件资源管理器空白处双击弹出快速导航菜单。</li><li><strong>在空白处点击中键</strong>：复选框（默认开启）。在桌面、文件资源管理器或文件选择对话框中点击鼠标中键弹出快速导航菜单。</li></ul><p>双击这种形式只有桌面和文件资源管理器支持；第三方文件管理器只认鼠标中键。指针位于 Lertaro 自己的卡片之上时，这两种触发都会被跳过；而即便黑名单或全屏状态本会屏蔽全局触发，文件管理器和文件对话框上的这两种触发依然保持有效。</p><h3 id="录制快捷键" tabindex="-1">录制快捷键 <a class="header-anchor" href="#录制快捷键" aria-label="Permalink to &quot;录制快捷键&quot;">​</a></h3><p>每一次按键都会进入录制框，而不是背后的那个应用，因此录制框本身就构成了一套手势：</p><ul><li><strong><code>Escape</code></strong>：取消录制并清空该值。没有“放弃并还原”这一说，按下的瞬间框子就空了。</li><li><strong><code>✕</code></strong> 清空录制框；<strong><code>↺</code></strong> 还原本行的出厂默认值。两者同一时刻只显示其中一个：已设置组合键时显示清除，清空之后显示还原。</li><li><strong>单独的修饰键</strong>（<code>Ctrl</code>、<code>Alt</code>、<code>Shift</code>）只在那些单按即有意义的行上才被接受，即唤起快捷键（由此变为双击模式）与跳转修饰键。在普通的组合键行上，按下并松开一个孤立修饰键会<strong>清空</strong>该行，而不是存下一个永远无法触发的值。</li><li><strong>Windows 已占用的组合键</strong>（<code>Win+E</code>、<code>Win+D</code> 等）会被拒绝：取值被强制置空，因此录制框直接变空白。</li><li><strong>不做冲突检测。</strong> 两行绑定同一个组合键也不会有任何提示；只有收藏项的快捷键会报告重复或被系统拒绝的组合，而且是在你应用之后才报告。</li></ul><h3 id="收藏项专属快捷键" tabindex="-1">收藏项专属快捷键 <a class="header-anchor" href="#收藏项专属快捷键" aria-label="Permalink to &quot;收藏项专属快捷键&quot;">​</a></h3><p>每一个收藏项（<a href="./favorites.html"><strong>设置 → 收藏夹</strong></a>）都可以带上自己的一份<strong>操作系统级全局</strong>快捷键，即使 Lertaro 没有打开任何窗口它同样生效，并能把前台文件管理器直接跳到该文件夹。与上面的录制行不同，它必须搭配修饰键、拒绝孤立修饰键，也不能使用 <code>F12</code>。</p><h2 id="_2-插件动作-plugin-actions" tabindex="-1">2. 插件动作（Plugin Actions） <a class="header-anchor" href="#_2-插件动作-plugin-actions" aria-label="Permalink to &quot;2. 插件动作（Plugin Actions）&quot;">​</a></h2><p>各插件注册的专属动作快捷键（例如内置的文件操作：复制路径 <code>Ctrl+Shift+C</code>、复制名称 <code>Shift+C</code>、剪切 <code>Ctrl+X</code>、复制 <code>Ctrl+C</code>、粘贴 <code>Ctrl+V</code>、删除 <code>Delete</code>、彻底删除 <code>Shift+Delete</code> 等）均汇集于此。</p><ul><li><strong>分组查看</strong>：按注册动作的来源插件清晰分组。</li><li><strong>独立重录</strong>：每个动作均配有专属的按键录制框，点击即可按下新按键进行覆盖绑定。</li></ul><h2 id="_3-进程黑名单-process-blacklist" tabindex="-1">3. 进程黑名单（Process Blacklist） <a class="header-anchor" href="#_3-进程黑名单-process-blacklist" aria-label="Permalink to &quot;3. 进程黑名单（Process Blacklist）&quot;">​</a></h2><p>用于配置特定前台应用程序的静默放行机制。当黑名单中的程序处于系统前台聚焦状态时，Lertaro 会完全放行所有全局快捷键与鼠标触发手势，绝不进行拦截。</p><ul><li><strong>不区分大小写</strong>：添加 <code>game.exe</code> 或 <code>game</code> 均可生效。</li><li><strong>单条添加</strong>：在单条输入框中输入进程名，点击<strong>添加进程</strong>按钮。</li><li><strong>批量管理</strong>：支持点击<strong>生成文本</strong>将当前黑名单导出为多行文本，或在多行文本框中直接粘贴编辑后点击<strong>应用到列表</strong>进行一键批量导入。</li><li><strong>文件对话框安全豁免</strong>：即使某个程序处于黑名单中，当它弹出系统文件选择对话框时，Lertaro 的内嵌搜索与鼠标快速导航依然会被安全放行，确保文件选取效率不受影响。</li></ul>',22)])])}const p=e(s,[["render",i]]);export{u as __pageData,p as default};
